import{_ as c,r as t,o as l,c as r,e,a as s,d as a,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"模型 - October CMS - 3.x","titleTemplate":false,"description":"将数据库表列直接映射到 PHP 对象。","frontmatter":{"subtitle":"将数据库表列直接映射到 PHP 对象。"},"headers":[{"level":2,"title":"定义模型","slug":"定义模型","link":"#定义模型","children":[{"level":3,"title":"支持的属性","slug":"支持的属性","link":"#支持的属性","children":[{"level":4,"title":"主键","slug":"主键","link":"#主键","children":[]},{"level":4,"title":"自增","slug":"自增","link":"#自增","children":[]},{"level":4,"title":"时间戳","slug":"时间戳","link":"#时间戳","children":[]},{"level":4,"title":"存储为 JSON 的值","slug":"存储为-json-的值","link":"#存储为-json-的值","children":[]}]}]},{"level":2,"title":"模型事件","slug":"模型事件","link":"#模型事件","children":[{"level":3,"title":"基本用法","slug":"基本用法","link":"#基本用法","children":[]}]},{"level":2,"title":"扩展模型","slug":"扩展模型","link":"#扩展模型","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/extend/system/models.md","filePath":"3.x/zh-cn/extend/system/models.md"}'),d={name:"3.x/zh-cn/extend/system/models.md"};function u(k,n,g,h,f,m){const p=t("pre-heading"),o=t("post-heading");return l(),r("div",null,[e(p),n[0]||(n[0]=s("h1",null,"模型",-1)),e(o),n[1]||(n[1]=s("p",null,[a("October CMS 提供了一个优雅而简洁的 Active Record 实现，用于与数据库交互，基于 "),s("a",{href:"http://laravel.com/docs/eloquent",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Laravel 的 Eloquent"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a('。每个数据库表都有一个对应的"模型"，用于与该表进行交互。模型允许你查询表中的数据，以及向表中插入新记录。')],-1)),n[2]||(n[2]=i(`<p>模型类位于插件目录的 <strong>models</strong> 子目录中。以下是模型目录结构的示例。</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>models</code>
|           |   ├── post  <em>← 配置目录</em>
|           |   |   ├── fields.yaml  <em>← 配置文件</em>
|           |   |   └── columns.yaml  <em>← 配置文件</em>
|           |   └── Post.php  <em>← 模型类</em>
|           └── Plugin.php</p>
</code></pre><p>模型配置目录可以包含模型的<a href="./../../element/form-fields.html">表单字段定义</a>。模型配置目录名称与以小写形式书写的模型类名匹配。</p><h2 id="定义模型"><a href="#定义模型" class="header-anchor">#</a> 定义模型</h2><p><code>create:model</code> 命令会生成新模型所需的文件。第一个参数指定作者和插件名称。第二个参数指定模型类名。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:model Acme.Blog Post
</code></pre></div><p>在大多数情况下，你应该为每个数据库表创建一个模型类。所有模型类必须继承 <code>Model</code> 类。在插件中使用的模型的最基本表示如下所示。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$table</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_blog_posts&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>$table</code> 受保护字段指定与模型对应的数据库表。表名由作者、插件和记录类型名称的复数形式以蛇形命名法组成。</p><h3 id="支持的属性"><a href="#支持的属性" class="header-anchor">#</a> 支持的属性</h3><p>除了<a href="./traits.html">模型 Trait</a> 提供的属性外，模型上还有一些标准属性。例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$exists</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;last_seen_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;permissions&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$guarded</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>$primaryKey</strong></td><td>用于标识模型的主键名称。</td></tr><tr><td><strong>$incrementing</strong></td><td>布尔值，如果为 false，则表示主键不是自增整数值。</td></tr><tr><td><strong>$exists</strong></td><td>布尔值，如果为 true，则表示模型已存在。</td></tr><tr><td><strong>$dates</strong></td><td>获取后值会被转换为 Carbon/DateTime 对象的实例。</td></tr><tr><td><strong>$timestamps</strong></td><td>布尔值，如果为 true，将自动设置 created_at 和 updated_at 字段。</td></tr><tr><td><strong>$jsonable</strong></td><td>保存前值会被编码为 JSON，获取后转换为数组。</td></tr><tr><td><strong>$fillable</strong></td><td>可批量赋值的字段。</td></tr><tr><td><strong>$guarded</strong></td><td>受保护的不允许批量赋值的字段。</td></tr><tr><td><strong>$visible</strong></td><td><a href="./../database/serialization.html">序列化模型数据</a>时可见的字段。</td></tr><tr><td><strong>$hidden</strong></td><td><a href="./../database/serialization.html">序列化模型数据</a>时隐藏的字段。</td></tr><tr><td><strong>$connection</strong></td><td>包含模型默认使用的<a href="./../../setup/database-config.html">连接名称</a>的字符串。</td></tr></tbody></table></div><h4 id="主键"><a href="#主键" class="header-anchor">#</a> 主键</h4><p>模型将假定每个表都有一个名为 <code>id</code> 的主键列。你可以定义 <code>$primaryKey</code> 属性来覆盖此约定。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="自增"><a href="#自增" class="header-anchor">#</a> 自增</h4><p>模型将假定主键是一个自增整数值，这意味着默认情况下主键将自动转换为整数。如果你希望使用非自增或非数字主键，则必须将公共属性 <code>$incrementing</code> 设置为 false。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Message</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$incrementing</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="时间戳"><a href="#时间戳" class="header-anchor">#</a> 时间戳</h4><p>默认情况下，模型期望表中存在 <code>created_at</code> 和 <code>updated_at</code> 列。如果你不希望这些列被自动管理，请将模型上的 <code>$timestamps</code> 属性设置为 <code>false</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果你需要自定义时间戳的格式，请在模型上设置 <code>$dateFormat</code> 属性。此属性决定日期属性在数据库中的存储方式，以及模型序列化为数组或 JSON 时的格式。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$dateFormat</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;U&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="存储为-json-的值"><a href="#存储为-json-的值" class="header-anchor">#</a> 存储为 JSON 的值</h4><p>当属性名称传递给 <code>$jsonable</code> 属性时，值将在存储到数据库时序列化为 JSON，在获取时反序列化。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="模型事件"><a href="#模型事件" class="header-anchor">#</a> 模型事件</h2><p>模型会触发多个事件，允许你在模型生命周期的各个节点进行挂钩。事件允许你在每次特定模型类在数据库中保存或更新时轻松执行代码。事件通过覆盖类中的特殊方法来定义，以下方法覆盖可用：</p><div class="table"><table tabindex="0"><thead><tr><th>事件</th><th>描述</th></tr></thead><tbody><tr><td><strong>beforeCreate</strong></td><td>模型首次创建时，保存之前。</td></tr><tr><td><strong>afterCreate</strong></td><td>模型首次创建时，保存之后。</td></tr><tr><td><strong>beforeSave</strong></td><td>模型创建或更新时，保存之前。</td></tr><tr><td><strong>afterSave</strong></td><td>模型创建或更新时，保存之后。</td></tr><tr><td><strong>beforeValidate</strong></td><td>提供的模型数据验证之前。</td></tr><tr><td><strong>afterValidate</strong></td><td>提供的模型数据验证之后。</td></tr><tr><td><strong>beforeUpdate</strong></td><td>现有模型保存之前。</td></tr><tr><td><strong>afterUpdate</strong></td><td>现有模型保存之后。</td></tr><tr><td><strong>beforeDelete</strong></td><td>现有模型删除之前。</td></tr><tr><td><strong>afterDelete</strong></td><td>现有模型删除之后。</td></tr><tr><td><strong>beforeRestore</strong></td><td>软删除的模型恢复之前。</td></tr><tr><td><strong>afterRestore</strong></td><td>软删除的模型恢复之后。</td></tr><tr><td><strong>beforeFetch</strong></td><td>现有模型填充之前。</td></tr><tr><td><strong>afterFetch</strong></td><td>现有模型填充之后。</td></tr></tbody></table></div><p>以下是使用事件的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="基本用法"><a href="#基本用法" class="header-anchor">#</a> 基本用法</h3><p>每当新模型第一次保存时，<code>beforeCreate</code> 和 <code>afterCreate</code> 事件将触发。如果模型已存在于数据库中并调用了 <code>save</code> 方法，则 <code>beforeUpdate</code> / <code>afterUpdate</code> 事件将触发。但是，在两种情况下，<code>beforeSave</code> / <code>afterSave</code> 事件都会触发。</p><p>例如，让我们定义一个事件监听器，在模型首次创建时填充 <code>slug</code> 属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>从事件返回 <code>false</code> 将取消 <code>save</code> / <code>update</code> 操作。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">isValid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>可以使用 <code>original</code> 属性访问旧值。例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">afterUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">!==</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">original</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Title has changed</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>你可能会发现使用<a href="./../database/relations.html">延迟绑定</a>创建的关联（例如：文件附件）在模型事件中尚不可用。要提前访问它们，请在关联上使用 <code>withDeferred</code> 数据库查询方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$avatar</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">avatar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withDeferred</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$gallery</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">gallery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withDeferred</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>你可以使用 <code>bindEvent</code> 方法从外部为单个模型实例绑定<a href="./../services/event.html">本地事件</a>。事件名称应与方法覆盖名称相同，并以 <code>model.</code> 为前缀。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeCreate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="扩展模型"><a href="#扩展模型" class="header-anchor">#</a> 扩展模型</h2><p>由于模型<a href="./behaviors.html">已准备好使用行为</a>，它们可以使用静态 <code>extend</code> 方法进行扩展。该方法接受一个闭包并将模型对象传递给它。</p><p>在闭包内部，你可以向模型添加关联。在这里，我们扩展 <code>User</code> 模型以包含一个引用 <code>Profile</code> 模型的 profile（has one）关联。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">hasOne</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;profile&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token class-name static-context">Profile</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>这种方法也可以用于绑定本地事件，以下代码监听 <code>model.beforeSave</code> 事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeSave&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>此外，还存在一些方法用于扩展受保护的模型属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Add cast attributes</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addCasts</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;some_extended_field&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;int&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Add a date attribute</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDateAttribute</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_at&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Adds fillable or jsonable fields</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addFillable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addJsonable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;some_data&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>通常，放置代码的最佳位置是在你的<a href="./../extending.html">插件注册文件</a> <code>boot</code> 方法中，因为它会在每次请求时运行，确保你对模型所做的扩展在任何地方都可用。</p><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../database/model.html">查询模型</a></li><li><a href="./../database/traits.html">模型 Trait</a></li></ul></div>`,55))])}const y=c(d,[["render",u]]);export{v as __pageData,y as default};
